DECLARE
  l_savepoint_name          VARCHAR2(30) := 'TEST_HEADCOUNT_SP';
  l_failure_count           PLS_INTEGER := 0;

  l_match_department_id     NUMBER;
  l_expected_match_count    NUMBER;
  l_actual_match_count      NUMBER;

  l_no_match_department_id  NUMBER;
  l_expected_no_match_count NUMBER;
  l_actual_no_match_count   NUMBER;

  l_expected_null_count     NUMBER := 0;
  l_actual_null_count       NUMBER;

  PROCEDURE check_result(
    p_check_name      IN VARCHAR2,
    p_expected_value  IN VARCHAR2,
    p_actual_value    IN VARCHAR2,
    p_failed          IN BOOLEAN
  ) IS
  BEGIN
    IF p_failed THEN
      l_failure_count := l_failure_count + 1;
      DBMS_OUTPUT.PUT_LINE(
        'FAIL: ' || p_check_name ||
        ' expected=' || NVL(p_expected_value, '<NULL>') ||
        ' actual=' || NVL(p_actual_value, '<NULL>')
      );
    ELSE
      DBMS_OUTPUT.PUT_LINE(
        'PASS: ' || p_check_name ||
        ' expected=' || NVL(p_expected_value, '<NULL>') ||
        ' actual=' || NVL(p_actual_value, '<NULL>')
      );
    END IF;
  END check_result;
BEGIN
  SAVEPOINT TEST_HEADCOUNT_SP;

  -- Check 1: a department_id that has at least one matching row.
  BEGIN
    SELECT MAX(department_id)
      INTO l_match_department_id
      FROM employees
     WHERE department_id IS NOT NULL;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      l_match_department_id := NULL;
  END;

  IF l_match_department_id IS NULL THEN
    check_result(
      p_check_name     => 'headcount with matching department_id',
      p_expected_value => 'a department_id with at least one row',
      p_actual_value   => 'no suitable department_id found in employees',
      p_failed         => TRUE
    );
  ELSE
    SELECT COUNT(*)
      INTO l_expected_match_count
      FROM employees
     WHERE department_id = l_match_department_id;

    l_actual_match_count := HARNESS_APP.headcount(l_match_department_id);

    check_result(
      p_check_name     => 'headcount with matching department_id',
      p_expected_value => TO_CHAR(l_expected_match_count),
      p_actual_value   => TO_CHAR(l_actual_match_count),
      p_failed         => l_actual_match_count <> l_expected_match_count
    );
  END IF;

  -- Check 2: a department_id that matches no row.
  BEGIN
    SELECT NVL(MAX(department_id), -1) + 1
      INTO l_no_match_department_id
      FROM employees
     WHERE department_id IS NOT NULL;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      l_no_match_department_id := -1;
  END;

  SELECT COUNT(*)
    INTO l_expected_no_match_count
    FROM employees
   WHERE department_id = l_no_match_department_id;

  IF l_expected_no_match_count <> 0 THEN
    check_result(
      p_check_name     => 'headcount with no-match department_id',
      p_expected_value => '0',
      p_actual_value   => 'chosen department_id matched rows: ' ||
                          TO_CHAR(l_no_match_department_id),
      p_failed         => TRUE
    );
  ELSE
    l_actual_no_match_count := HARNESS_APP.headcount(l_no_match_department_id);

    check_result(
      p_check_name     => 'headcount with no-match department_id',
      p_expected_value => '0',
      p_actual_value   => TO_CHAR(l_actual_no_match_count),
      p_failed         => l_actual_no_match_count <> 0
    );
  END IF;

  -- Check 3: NULL argument.
  -- The function compares department_id = p_department_id, so a NULL
  -- argument matches no row and the expected result is 0.
  l_actual_null_count := HARNESS_APP.headcount(NULL);

  check_result(
    p_check_name     => 'headcount with NULL department_id',
    p_expected_value => '0',
    p_actual_value   => TO_CHAR(l_actual_null_count),
    p_failed         => l_actual_null_count <> l_expected_null_count
  );

  DBMS_OUTPUT.PUT_LINE(
    'Summary: failure_count=' || TO_CHAR(l_failure_count)
  );

  ROLLBACK TO TEST_HEADCOUNT_SP;

  IF l_failure_count <> 0 THEN
    RAISE_APPLICATION_ERROR(-20999, 'headcount test block failed');
  END IF;
EXCEPTION
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error: ' || SQLERRM);
    ROLLBACK TO TEST_HEADCOUNT_SP;
    RAISE;
END;
```

The first check covers a `department_id` that has at least one row in `employees`. It chooses the maximum non-NULL `department_id`, computes the expected count independently with a separate `COUNT(*)`, calls `HARNESS_APP.headcount`, and compares the result. If no suitable department exists, the check prints `FAIL` and counts as a failure.

The second check covers a `department_id` that should match no row. It chooses a value greater than the maximum non-NULL `department_id`, confirms with `COUNT(*)` that it matches no rows, calls the function, and expects `0`. If the chosen value unexpectedly matches rows, the check prints `FAIL` and counts as a failure.

The third check covers a `NULL` argument. Because the function uses `department_id = p_department_id`, a `NULL` argument matches no row, so the expected result is `0`, not the count of rows where `department_id IS NULL`.

